INSERT INTO public.erp_ajuda_campo (chave, rota, grupo, vertical, ordem, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum)
VALUES
('projetos.clientes.kpi.em_aberto','/dashboard/projetos/clientes','Indicadores','hub_projetos',40,'Em negociação','Indicador calculado, não se preenche. Soma o valor das oportunidades ainda em aberto (fora de Ganho e Perdido) dos clientes ativos; usa o valor da proposta quando já existe, senão o estimado.','Mostra quanto dinheiro está na mesa com a carteira de clientes agora.','R$ 194 mil','Esquecer de marcar Ganho ou Perdido no funil: a oportunidade encerrada continua somando aqui.'),
('projetos.clientes.comercial','/dashboard/projetos/clientes','Lista','hub_projetos',41,'Resumo comercial do cliente','Nada a preencher: conta, para o cliente, as oportunidades em aberto (e o valor), as ganhas, as propostas, as visitas técnicas e as obras.','Mostra em que ponto da jornada Cliente → Oportunidade → Visita → Proposta → Obra cada cliente está, sem abrir outra tela.','2 em aberto · R$ 136 mil · 1 proposta · 1 visita · 0 obras','Cadastrar a oportunidade sem escolher o cliente: ela não aparece aqui.'),
('projetos.clientes.acao.proposta','/dashboard/projetos/clientes','Ações','hub_projetos',42,'Nova proposta','Abre a tela de propostas (orçamentos) para montar a proposta com serviços do catálogo; escolha este cliente nela.','Leva o cliente adiante na cadeia comercial até o pedido e a obra.','Proposta de piso epóxi para o Mercado Central','Digitar o cliente à mão na proposta em vez de escolher do cadastro: ela não liga a este cliente.'),
('projetos.clientes.oportunidades','/dashboard/projetos/clientes','Lista','hub_projetos',43,'Oportunidades deste cliente','Lista calculada das oportunidades do funil ligadas ao cliente, com a etapa e o valor. Toque para abrir a oportunidade.','Mostra o histórico comercial do cliente e o que ainda está em negociação.','Ampliação do galpão · Negociação · R$ 41.000,00','Abrir uma oportunidade nova para um negócio que já está no funil.'),
('projetos.clientes.propostas','/dashboard/projetos/clientes','Lista','hub_projetos',44,'Propostas deste cliente','Lista calculada das propostas (orçamentos) emitidas para o cliente, com a situação e o total. Toque para abrir a proposta.','Mostra o que já foi oferecido ao cliente e por quanto, antes de negociar de novo.','Proposta 0007 · aprovado · R$ 84.000,00','Proposta duplicada para o mesmo serviço: o cliente recebe dois preços.')
